/**
 * @advisory v5.3.2 — order-independent selector build pipeline with retryable phases. Node/fs only.
 * @advisory v5.3.3 — persistent checkpoint + resume across phases.
 * @advisory v5.3.4 — distributed checkpoint manifest coordination.
 */
import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import {
  clearDistributedCheckpointManifest,
  DEFAULT_BUILD_CHECKPOINT_PATH,
  readReconciledBuildCheckpoint,
  recordNodeCheckpoint,
  reconcileAndPersistCheckpoints,
  type BuildCheckpoint,
  type BuildPhaseName,
} from "@/lib/selector-core/selector-distributed-checkpoint-manager";
import {
  assertBundleRegistryConsistency,
  DEFAULT_BUNDLE_MANIFEST_PATH,
  type BundleRegistryConsistencyResult,
} from "@/lib/selector-core/selector-bundle-registry-consistency-check";
import { assertBoundedBundle } from "@/lib/selector-core/selector-build-dependency-guard";
import { reconcilePointerWithRetrySync } from "@/lib/selector-core/selector-distributed-pointer-guard";
import { readPointer, DEFAULT_POINTER_PATH } from "@/lib/selector-core/selector-snapshot-atomic-switch";
import {
  DEFAULT_GENERATED_SNAPSHOTS_DIR,
  DEFAULT_SNAPSHOT_REGISTRY_GENERATED_PATH,
  syncSnapshotBundleDetailed,
} from "@/lib/selector-core/selector-snapshot-bundle-sync";
import {
  classifySnapshotVersions,
} from "@/lib/selector-core/selector-snapshot-lifecycle-manager";
import { sortVersionsByRecency } from "@/lib/selector-core/selector-snapshot-pruner";
import {
  planSnapshotGc,
} from "@/lib/selector-core/selector-snapshot-gc-policy";
import { validateSnapshotSemanticsOrThrow } from "@/lib/selector-core/selector-snapshot-semantic-validator";
import { validateSnapshotOrThrow } from "@/lib/selector-core/selector-snapshot-schema-validator";
import {
  buildAndPublishSnapshot,
  DEFAULT_SNAPSHOT_STORE_DIR,
  getSnapshot,
  listSnapshots,
  readManifest,
} from "@/lib/selector-core/selector-snapshot-registry";
import type { GcPlan } from "@/lib/selector-core/selector-snapshot-gc-policy";
import { auditSelectorSystemComplexity } from "@/lib/selector-core/selector-determinism-gate-audit";
import type { ComplexityAuditResult } from "@/lib/selector-core/selector-determinism-gate";
import {
  resolveEnforcerMode,
  runUnifiedPolicyCheck,
  type UnifiedPolicyCheckResult,
} from "@/lib/selector-core/selector-api-usage-enforcer";
import type { ApiEnforcerReport } from "@/lib/selector-core/selector-api-enforcer-report";
import type { PolicyRuntimeConvergenceResult } from "@/lib/selector-core/selector-enforcement-ruleset";
import type { LifecycleClassification } from "@/lib/selector-core/selector-snapshot-lifecycle-manager";
import type { PromotionRegistryState } from "@/lib/selector-core/types";
import { debugObservation } from "@/lib/selector-core/selector-debug-observation";

export type BuildOrchestratorResult = {
  bundledVersions: string[];
  rollbackOnlyVersions: string[];
  consistency: BundleRegistryConsistencyResult;
  classification: LifecycleClassification;
  gcPlan: GcPlan;
  /** @advisory v5.5 — dev-only complexity audit attached post-build */
  complexityAudit?: ComplexityAuditResult;
  /** @advisory v6.0 — unified enforcement + convergence + canonical artifacts */
  unifiedPolicyReport?: UnifiedPolicyCheckResult;
  /** @deprecated v6.0 — use unifiedPolicyReport.enforcementReport */
  apiEnforcementReport?: ApiEnforcerReport;
  /** @deprecated v6.0 — use unifiedPolicyReport.convergenceReport */
  convergenceReport?: PolicyRuntimeConvergenceResult;
};

export type BuildOrchestratorOptions = {
  checkOnly?: boolean;
  registry?: PromotionRegistryState;
  storeDir?: string;
  pointerPath?: string;
  generatedSnapshotsDir?: string;
  registryGeneratedPath?: string;
  bundleManifestPath?: string;
  checkpointPath?: string;
};

export type { BuildPhaseName, BuildCheckpoint } from "@/lib/selector-core/selector-distributed-checkpoint-manager";

export type BuildPhaseResult<T = unknown> = {
  ok: boolean;
  phase: BuildPhaseName;
  result?: T;
  error?: string;
  retryable: boolean;
};

export {
  DEFAULT_BUILD_CHECKPOINT_PATH,
  DEFAULT_DISTRIBUTED_CHECKPOINT_MANIFEST_PATH,
} from "@/lib/selector-core/selector-distributed-checkpoint-manager";

const PHASE_ORDER: BuildPhaseName[] = [
  "validate",
  "build",
  "sync",
  "verify",
  "unifiedPolicyCheck",
];

export { PHASE_ORDER as SELECTOR_BUILD_PHASE_ORDER };

function resolveOptions(options: BuildOrchestratorOptions = {}) {
  return {
    storeDir: options.storeDir ?? DEFAULT_SNAPSHOT_STORE_DIR,
    pointerPath: options.pointerPath ?? DEFAULT_POINTER_PATH,
    generatedSnapshotsDir: options.generatedSnapshotsDir ?? DEFAULT_GENERATED_SNAPSHOTS_DIR,
    registryGeneratedPath: options.registryGeneratedPath ?? DEFAULT_SNAPSHOT_REGISTRY_GENERATED_PATH,
    bundleManifestPath: options.bundleManifestPath ?? DEFAULT_BUNDLE_MANIFEST_PATH,
    checkOnly: options.checkOnly ?? false,
    registry: options.registry,
    checkpointPath: options.checkpointPath ?? DEFAULT_BUILD_CHECKPOINT_PATH,
  };
}

export function buildOptionsFingerprint(options: BuildOrchestratorOptions = {}): string {
  const resolved = resolveOptions(options);
  return crypto
    .createHash("sha256")
    .update(
      JSON.stringify({
        storeDir: resolved.storeDir,
        pointerPath: resolved.pointerPath,
        generatedSnapshotsDir: resolved.generatedSnapshotsDir,
        registryGeneratedPath: resolved.registryGeneratedPath,
        bundleManifestPath: resolved.bundleManifestPath,
        checkOnly: resolved.checkOnly,
        hasRegistry: Boolean(options.registry),
      }),
    )
    .digest("hex");
}

export function readBuildCheckpoint(
  _checkpointPath = DEFAULT_BUILD_CHECKPOINT_PATH,
  optionsFingerprint?: string,
): BuildCheckpoint | null {
  return readReconciledBuildCheckpoint(optionsFingerprint);
}

export function writeBuildCheckpoint(
  checkpoint: BuildCheckpoint,
  _checkpointPath = DEFAULT_BUILD_CHECKPOINT_PATH,
): void {
  recordNodeCheckpoint(checkpoint);
}

export function clearBuildCheckpoint(
  _checkpointPath = DEFAULT_BUILD_CHECKPOINT_PATH,
): void {
  clearDistributedCheckpointManifest();
}

export { reconcileAndPersistCheckpoints };

function isPhaseCompleteInCheckpoint(
  phase: BuildPhaseName,
  fingerprint: string,
  checkpoint: BuildCheckpoint | null,
): boolean {
  return (
    checkpoint?.optionsFingerprint === fingerprint &&
    checkpoint.phaseResults[phase]?.ok === true
  );
}

function recordPhaseCheckpoint(
  phase: BuildPhaseName,
  ok: boolean,
  options: BuildOrchestratorOptions,
): void {
  const fingerprint = buildOptionsFingerprint(options);
  const existing = readReconciledBuildCheckpoint(fingerprint);
  const checkpoint: BuildCheckpoint = {
    lastCompletedPhase: ok ? phase : existing?.lastCompletedPhase ?? null,
    completedAt: new Date().toISOString(),
    optionsFingerprint: fingerprint,
    phaseResults: {
      ...(existing?.optionsFingerprint === fingerprint ? existing.phaseResults : {}),
      [phase]: { ok, at: new Date().toISOString() },
    },
  };
  recordNodeCheckpoint(checkpoint);
}

export function validateStoreSnapshots(storeDir = DEFAULT_SNAPSHOT_STORE_DIR): void {
  for (const version of listSnapshots(storeDir)) {
    const snapshot = getSnapshot(version, storeDir);
    validateSnapshotOrThrow(snapshot);
  }
}

export function validatePhase(
  options: BuildOrchestratorOptions = {},
): BuildPhaseResult<{ classification: LifecycleClassification; gcPlan: GcPlan }> {
  try {
    const resolved = resolveOptions(options);
    validateStoreSnapshots(resolved.storeDir);

    const pointer = readPointer(resolved.pointerPath);
    const manifest = readManifest(path.join(resolved.storeDir, "manifest.json"));
    const storeVersions = listSnapshots(resolved.storeDir);
    const classification = classifySnapshotVersions(storeVersions, pointer, manifest);
    const gcPlan = planSnapshotGc(classification, manifest);

    const baselineVersion = pointer.activeVersion || manifest.activeVersion;
    if (baselineVersion && storeVersions.includes(baselineVersion)) {
      const baseline = getSnapshot(baselineVersion, resolved.storeDir);
      const recency = sortVersionsByRecency(storeVersions);
      const baselineIndex = recency.indexOf(baselineVersion);
      for (const version of storeVersions) {
        if (version === baselineVersion) continue;
        const versionIndex = recency.indexOf(version);
        const lifecycle = manifest.lifecycle?.[version];
        const isPipeline =
          lifecycle === "staged" ||
          lifecycle === "validated" ||
          lifecycle === "proposed";
        if (versionIndex > baselineIndex && !isPipeline) continue;
        const candidate = getSnapshot(version, resolved.storeDir);
        validateSnapshotSemanticsOrThrow(candidate, baseline);
      }
    }

    debugObservation.emit({
      module: "gc-policy",
      event: "planned",
      hint: `GC plan ready (${gcPlan.candidates?.length ?? 0} candidate(s)); inspect selector-snapshot-gc-policy`,
    });

    return {
      ok: true,
      phase: "validate",
      result: { classification, gcPlan },
      retryable: true,
    };
  } catch (error) {
    return {
      ok: false,
      phase: "validate",
      error: error instanceof Error ? error.message : String(error),
      retryable: true,
    };
  }
}

export function unifiedPolicyCheckPhase(
  _options: BuildOrchestratorOptions = {},
): BuildPhaseResult<{ report: UnifiedPolicyCheckResult }> {
  try {
    const report = runUnifiedPolicyCheck({ mode: resolveEnforcerMode() });
    if (report.shouldFail) {
      const enforcement = report.enforcementReport;
      return {
        ok: false,
        phase: "unifiedPolicyCheck",
        error: `Unified policy check failed (${enforcement.violations.length} import(s), ${enforcement.barrelViolations.length} barrel issue(s), severity=${report.convergenceReport.severity})`,
        retryable: false,
        result: { report },
      };
    }
    debugObservation.emit({
      module: "unifiedPolicyCheck",
      event: "completed",
      hint: "Policy convergence path: runUnifiedPolicyCheck → deriveConvergenceReport → ruleset",
    });

    return {
      ok: true,
      phase: "unifiedPolicyCheck",
      result: { report },
      retryable: true,
    };
  } catch (error) {
    return {
      ok: false,
      phase: "unifiedPolicyCheck",
      error: error instanceof Error ? error.message : String(error),
      retryable: false,
    };
  }
}

export function buildPhase(
  options: BuildOrchestratorOptions = {},
): BuildPhaseResult<{ published: boolean }> {
  try {
    const resolved = resolveOptions(options);
    if (resolved.checkOnly || !resolved.registry) {
      return { ok: true, phase: "build", result: { published: false }, retryable: true };
    }
    buildSnapshotArtifacts(resolved.registry, resolved.storeDir, resolved.pointerPath);
    return { ok: true, phase: "build", result: { published: true }, retryable: true };
  } catch (error) {
    return {
      ok: false,
      phase: "build",
      error: error instanceof Error ? error.message : String(error),
      retryable: true,
    };
  }
}

export function syncPhase(
  options: BuildOrchestratorOptions = {},
): BuildPhaseResult<{ bundledVersions: string[]; rollbackOnlyVersions: string[] }> {
  try {
    const resolved = resolveOptions(options);
    const pointer = reconcilePointerWithRetrySync(() => readPointer(resolved.pointerPath));
    const manifest = readManifest(path.join(resolved.storeDir, "manifest.json"));
    const storeVersions = listSnapshots(resolved.storeDir);
    const classification = classifySnapshotVersions(storeVersions, pointer, manifest);
    assertBoundedBundle(classification.bundleVersions.length);

    const syncResult = syncSnapshotBundleDetailed(
      resolved.storeDir,
      resolved.generatedSnapshotsDir,
      resolved.registryGeneratedPath,
      classification.bundleVersions,
      resolved.pointerPath,
      resolved.bundleManifestPath,
    );

    debugObservation.emit({
      module: "snapshot-sync",
      event: "bundled",
      hint: `Bundled ${syncResult.bundledVersions.length} version(s); verify pointer + bundle manifest`,
    });

    return {
      ok: true,
      phase: "sync",
      result: syncResult,
      retryable: true,
    };
  } catch (error) {
    return {
      ok: false,
      phase: "sync",
      error: error instanceof Error ? error.message : String(error),
      retryable: true,
    };
  }
}

export function verifyPhase(
  options: BuildOrchestratorOptions = {},
  bundledVersions?: string[],
): BuildPhaseResult<{ consistency: BundleRegistryConsistencyResult }> {
  try {
    const resolved = resolveOptions(options);
    const consistency = assertBundleRegistryConsistency({
      storeDir: resolved.storeDir,
      generatedSnapshotsDir: resolved.generatedSnapshotsDir,
      registryGeneratedPath: resolved.registryGeneratedPath,
      bundledVersions,
      pointerPath: resolved.pointerPath,
    });
    return {
      ok: true,
      phase: "verify",
      result: { consistency },
      retryable: true,
    };
  } catch (error) {
    return {
      ok: false,
      phase: "verify",
      error: error instanceof Error ? error.message : String(error),
      retryable: true,
    };
  }
}

export function buildSnapshotArtifacts(
  registry: PromotionRegistryState,
  storeDir = DEFAULT_SNAPSHOT_STORE_DIR,
  pointerPath = DEFAULT_POINTER_PATH,
): void {
  buildAndPublishSnapshot(registry, { storeDir, pointerPath });
}

export function runSelectorBuildPipeline(
  options: BuildOrchestratorOptions = {},
): BuildOrchestratorResult {
  return executeBuildPipeline(options, false);
}

export function resumeSelectorBuildPipeline(
  options: BuildOrchestratorOptions = {},
): BuildOrchestratorResult {
  return executeBuildPipeline(options, true);
}

function readBundledVersionsFromManifest(bundleManifestPath: string): {
  bundledVersions: string[];
  rollbackOnlyVersions: string[];
} {
  if (!fs.existsSync(bundleManifestPath)) {
    return { bundledVersions: [], rollbackOnlyVersions: [] };
  }
  const manifest = JSON.parse(fs.readFileSync(bundleManifestPath, "utf8")) as {
    versions?: string[];
    rollbackVersions?: string[];
  };
  return {
    bundledVersions: manifest.versions ?? [],
    rollbackOnlyVersions: manifest.rollbackVersions ?? [],
  };
}

function executeBuildPipeline(
  options: BuildOrchestratorOptions,
  resume: boolean,
): BuildOrchestratorResult {
  const resolved = resolveOptions(options);
  const fingerprint = buildOptionsFingerprint(options);
  const checkpoint = resume ? readReconciledBuildCheckpoint(fingerprint) : null;
  const skipPhase = (phase: BuildPhaseName): boolean =>
    resume && isPhaseCompleteInCheckpoint(phase, fingerprint, checkpoint);

  const validate = skipPhase("validate")
    ? { ok: true, phase: "validate" as const, retryable: true }
    : validatePhase(options);
  if (!skipPhase("validate")) {
    recordPhaseCheckpoint("validate", validate.ok, options);
  }
  if (!validate.ok) {
    throw new Error(`validatePhase failed: ${validate.error}`);
  }
  const validateMeta = validate.result ?? validatePhase(options).result;
  if (!validateMeta) {
    throw new Error("validatePhase failed: missing classification");
  }

  const build = skipPhase("build")
    ? { ok: true, phase: "build" as const, retryable: true, result: { published: false } }
    : buildPhase(options);
  if (!skipPhase("build")) {
    recordPhaseCheckpoint("build", build.ok, options);
  }
  if (!build.ok) {
    throw new Error(`buildPhase failed: ${build.error}`);
  }

  let syncResult: { bundledVersions: string[]; rollbackOnlyVersions: string[] };
  if (skipPhase("sync")) {
    syncResult = readBundledVersionsFromManifest(resolved.bundleManifestPath);
  } else {
    const sync = syncPhase(options);
    recordPhaseCheckpoint("sync", sync.ok, options);
    if (!sync.ok || !sync.result) {
      throw new Error(`syncPhase failed: ${sync.error}`);
    }
    syncResult = sync.result;
  }

  const verify = verifyPhase(options, syncResult.bundledVersions);
  if (!skipPhase("verify")) {
    recordPhaseCheckpoint("verify", verify.ok, options);
  }
  if (!verify.ok || !verify.result) {
    throw new Error(`verifyPhase failed: ${verify.error}`);
  }

  const unifiedPolicy = skipPhase("unifiedPolicyCheck")
    ? { ok: true, phase: "unifiedPolicyCheck" as const, retryable: true }
    : unifiedPolicyCheckPhase(options);
  if (!skipPhase("unifiedPolicyCheck")) {
    recordPhaseCheckpoint("unifiedPolicyCheck", unifiedPolicy.ok, options);
  }
  if (!unifiedPolicy.ok) {
    throw new Error(`unifiedPolicyCheckPhase failed: ${unifiedPolicy.error}`);
  }
  const unifiedPolicyReport =
    unifiedPolicy.result?.report ??
    runUnifiedPolicyCheck({ mode: resolveEnforcerMode() });

  clearDistributedCheckpointManifest();

  const pointer = readPointer(resolved.pointerPath);
  const manifest = readManifest(path.join(resolved.storeDir, "manifest.json"));
  const classification = classifySnapshotVersions(
    listSnapshots(resolved.storeDir),
    pointer,
    manifest,
  );

  const complexityAudit =
    typeof process !== "undefined" &&
    (process.env.NODE_ENV !== "production" ||
      process.env.SELECTOR_TELEMETRY_DEBUG === "true")
      ? auditSelectorSystemComplexity()
      : undefined;

  return {
    bundledVersions: syncResult.bundledVersions,
    rollbackOnlyVersions: syncResult.rollbackOnlyVersions,
    consistency: verify.result.consistency,
    classification,
    gcPlan: validateMeta.gcPlan,
    complexityAudit,
    unifiedPolicyReport,
    apiEnforcementReport: unifiedPolicyReport.enforcementReport,
    convergenceReport: unifiedPolicyReport.convergenceReport,
  };
}

export function runSelectorBuildPhase(
  phase: BuildPhaseName,
  options: BuildOrchestratorOptions = {},
): BuildPhaseResult {
  switch (phase) {
    case "validate":
      return validatePhase(options);
    case "unifiedPolicyCheck":
      return unifiedPolicyCheckPhase(options);
    case "build":
      return buildPhase(options);
    case "sync":
      return syncPhase(options);
    case "verify":
      return verifyPhase(options);
    default:
      return { ok: false, phase, error: `Unknown phase: ${phase}`, retryable: false };
  }
}

/**
 * @advisory v5.5 — single explainability entrypoint.
 * @advisory v5.6 — semantic routing + use-case bundles (runtime trace in selector-fallback-trace).
 */
import { SELECTOR_BASE_SNAPSHOT_V0 } from "@/lib/selector-core/selector-config-snapshot";
import {
  routeCausalExplanation,
  routeExistingCausalModel,
  type CausalRoutingResult,
  type CausalSemanticIntent,
} from "@/lib/selector-core/selector-causal-semantic-router";
import { createEmptyCausalModel } from "@/lib/selector-core/selector-core-causal-model";
import type {
  BuildCausalModelInput,
  UnifiedSelectorCausalModel,
} from "@/lib/selector-core/selector-causal-model-interface";
import {
  getTraceById,
  type FallbackTrace,
  type SelectorDecisionTrace,
} from "@/lib/selector-core/selector-decision-trace";
import {
  getLastFallbackTrace,
  recordFallbackTrace,
  traceFallbackResolution,
  type FallbackTraceInput,
} from "@/lib/selector-core/selector-fallback-trace";
import { getLastRuntimeContextSnapshot } from "@/lib/selector-core/selector-runtime-context-snapshot";
import type { SelectorRuntimeContext } from "@/lib/selector-core/selector-runtime-context-snapshot";
import type { GcPlan } from "@/lib/selector-core/selector-snapshot-gc-policy";
import type { SelectorRuntimeSnapshot } from "@/lib/selector-core/types";

export type {
  FallbackSource,
  FallbackTrace,
  FallbackRejectedSource,
  FallbackTraceInput,
} from "@/lib/selector-core/selector-fallback-trace";

export {
  traceFallbackResolution,
  getLastFallbackTrace,
  setLastFallbackTrace,
  isFallbackExplainabilityEnabled,
  __resetFallbackTraceForTests,
} from "@/lib/selector-core/selector-fallback-trace";

export type ExplainabilityDegradationMode = "NORMAL" | "DEGRADED" | "FORENSIC";

/** @deprecated v5.5 — mapped via toLegacyDegradationMode */
export type LegacyExplainabilityDegradationMode =
  | "FULL"
  | "PARTIAL"
  | "MINIMAL"
  | "FORENSIC_RECONSTRUCTED";

export function toLegacyDegradationMode(
  mode: ExplainabilityDegradationMode,
): LegacyExplainabilityDegradationMode {
  if (mode === "NORMAL") return "FULL";
  if (mode === "DEGRADED") return "MINIMAL";
  return "FORENSIC_RECONSTRUCTED";
}

export type FallbackExplainabilityResult = {
  mode: ExplainabilityDegradationMode;
  trace: FallbackTrace;
  warnings: string[];
  valid: true;
};

export type ReconstructFallbackInput = {
  expectedVersion: string;
  runtimeContext?: SelectorRuntimeContext;
  causalGraph?: UnifiedSelectorCausalModel;
  partialRegistry?: Record<string, SelectorRuntimeSnapshot>;
  partialRollback?: Record<string, SelectorRuntimeSnapshot>;
  pointerPrevious?: string;
  pointerEpoch?: number;
  manifestHashes?: Record<string, string>;
};

export type UnifiedExplanation = {
  traceId: string;
  decision?: SelectorDecisionTrace;
  fallback?: FallbackExplainabilityResult;
  gc?: GcExplanation;
  causalModel: UnifiedSelectorCausalModel;
  /** @deprecated v5.5 — use causalModel */
  causalIndex: UnifiedSelectorCausalModel;
  degradationMode: ExplainabilityDegradationMode;
  summary: string[];
  valid: true;
};

export type GcExplanation = {
  blocked: string[];
  temporalBlocked?: string[];
  reasons: string[];
};

function buildCausalInputFromExplainability(input: {
  decisionTrace?: SelectorDecisionTrace;
  fallbackTrace?: FallbackTrace | null;
  runtimeContext?: SelectorRuntimeContext | null;
  registryKeys?: string[];
  expectedVersion?: string;
  pointerEpoch?: number;
}): BuildCausalModelInput {
  const registryKeys = input.registryKeys ?? [];
  return {
    decisionTrace: input.decisionTrace,
    fallbackTrace: input.fallbackTrace,
    runtimeContext: input.runtimeContext,
    gcLineage:
      registryKeys.length > 0
        ? { nodes: registryKeys, edges: [], protected: registryKeys.slice(0, 1) }
        : input.fallbackTrace && !registryKeys.length
          ? undefined
          : input.expectedVersion
            ? {
                nodes: [input.expectedVersion],
                edges: [],
                protected: [input.expectedVersion],
              }
            : undefined,
  };
}

function routeForExplainability(
  intent: CausalSemanticIntent,
  buildInput: BuildCausalModelInput,
  existingModel?: UnifiedSelectorCausalModel,
): CausalRoutingResult {
  if (existingModel) {
    return routeExistingCausalModel(intent, existingModel);
  }
  return routeCausalExplanation(intent, buildInput);
}

function isRegistryComplete(
  expectedVersion: string,
  registryKeys: string[],
  registry: Record<string, SelectorRuntimeSnapshot>,
): boolean {
  return registryKeys.includes(expectedVersion) && !!registry[expectedVersion];
}

function buildMinimalForensicTrace(
  expectedVersion: string,
  pointerEpoch: number,
  pointerPrevious?: string,
): FallbackTrace {
  return {
    selectedSource: "v0",
    selectedVersion: SELECTOR_BASE_SNAPSHOT_V0.version,
    rejectedSources: [
      { source: "bundle", version: expectedVersion, reasonCode: "forensic_reconstruction" },
    ],
    reasonCodes: ["forensic_reconstruction", "fallback_to_v0"],
    pointerEpoch,
    recordedAt: Date.now(),
    selectionPath: [
      `forensic:${expectedVersion}:reconstructed`,
      pointerPrevious ? `previous:${pointerPrevious}:attempted` : "previous:none",
      `selected:v0:${SELECTOR_BASE_SNAPSHOT_V0.version}`,
    ],
  };
}

function resolveDegradationMode(input: {
  runtimeContext?: SelectorRuntimeContext;
  registryComplete: boolean;
  causalModel: UnifiedSelectorCausalModel;
}): ExplainabilityDegradationMode {
  if (!input.registryComplete) return "FORENSIC";
  if (!input.runtimeContext) return "DEGRADED";
  if (input.causalModel.events.length > 0) return "NORMAL";
  return "DEGRADED";
}

export function resolveExplainability(
  input: ReconstructFallbackInput,
): FallbackExplainabilityResult {
  const warnings: string[] = [];
  const registry = input.partialRegistry ?? {};
  const rollbackRegistry = input.partialRollback ?? {};
  const registryKeys = Object.keys(registry);
  const registryComplete = isRegistryComplete(
    input.expectedVersion,
    registryKeys,
    registry,
  );
  const pointerEpoch = input.pointerEpoch ?? input.runtimeContext?.pointerEpoch ?? 0;

  const buildInput = buildCausalInputFromExplainability({
    runtimeContext: input.runtimeContext,
    expectedVersion: input.expectedVersion,
    registryKeys,
    pointerEpoch,
    fallbackTrace: registryComplete
      ? undefined
      : {
          selectedSource: "bundle",
          selectedVersion: input.expectedVersion,
          rejectedSources: [],
          reasonCodes: ["partial_reconstruction"],
          pointerEpoch,
          recordedAt: Date.now(),
          selectionPath: [],
        },
  });

  const intent: CausalSemanticIntent = registryComplete ? "UX" : "FORENSIC";
  const routed = routeForExplainability(intent, buildInput, input.causalGraph);
  const causalModel = routed.model;

  const mode = resolveDegradationMode({
    runtimeContext: input.runtimeContext,
    registryComplete,
    causalModel,
  });

  let trace = buildMinimalForensicTrace(
    input.expectedVersion,
    pointerEpoch,
    input.pointerPrevious,
  );

  if (mode === "NORMAL" && registryComplete) {
    trace = traceFallbackResolution({
      expectedVersion: input.expectedVersion,
      registryKeys,
      registry,
      rollbackRegistry,
      pointerPrevious: input.pointerPrevious,
      pointerEpoch,
      manifestHashes: input.manifestHashes,
    });
  } else if (mode === "DEGRADED" && input.runtimeContext) {
    warnings.push("degraded_mode_runtime_context_only");
    trace = recordFallbackTrace(
      buildMinimalForensicTrace(input.expectedVersion, pointerEpoch, input.pointerPrevious),
    );
  } else {
    warnings.push("forensic_reconstruction_applied");
    const fallbackView = routed.views.find((v) => v.viewType === "fallback");
    const snapshotEvents = (fallbackView?.events ?? causalModel.events).filter(
      (e) => e.type === "fallback" || e.metadata.kind === "snapshot",
    );
    let resolved = false;
    for (const event of snapshotEvents) {
      const version = event.node.includes("/")
        ? (event.node.split("/")[1] ?? event.node)
        : event.node;
      if (registry[version] || rollbackRegistry[version]) {
        trace = traceFallbackResolution({
          expectedVersion: version,
          registryKeys: registry[version] ? registryKeys : [...registryKeys, version],
          registry,
          rollbackRegistry,
          pointerPrevious: input.pointerPrevious,
          pointerEpoch,
          manifestHashes: input.manifestHashes,
        });
        resolved = true;
        break;
      }
    }
    if (!resolved) {
      const reconstructed = traceFallbackResolution({
        expectedVersion: input.expectedVersion,
        registryKeys,
        registry,
        rollbackRegistry,
        pointerPrevious: input.pointerPrevious,
        pointerEpoch,
        manifestHashes: input.manifestHashes,
      });
      trace = recordFallbackTrace({
        ...reconstructed,
        reasonCodes: [
          ...reconstructed.reasonCodes,
          "partial_registry_reconstruction",
          input.causalGraph ? "causal_model_inferred" : "causal_model_synthesized",
        ],
        selectionPath:
          reconstructed.selectionPath.length > 0
            ? reconstructed.selectionPath
            : [`forensic:${input.expectedVersion}:reconstructed`],
      });
    }
  }

  return { mode, trace, warnings, valid: true };
}

/** @deprecated v5.5 — use resolveExplainability */
export function resolveFallbackExplainability(
  input: ReconstructFallbackInput,
): FallbackExplainabilityResult {
  return resolveExplainability(input);
}

export function reconstructFallbackChain(input: ReconstructFallbackInput): FallbackTrace {
  return resolveExplainability(input).trace;
}

function buildSummary(
  traceId: string,
  mode: ExplainabilityDegradationMode,
  decision?: SelectorDecisionTrace,
  fallback?: FallbackExplainabilityResult,
): string[] {
  const summary = [`traceId=${traceId}`, `degradationMode=${mode}`];
  if (decision?.outputDecision?.surface) {
    summary.push(`surface=${decision.outputDecision.surface}`);
  }
  if (fallback?.trace.selectedSource) {
    summary.push(
      `fallback=${fallback.trace.selectedSource}:${fallback.trace.selectedVersion}`,
    );
  }
  if (fallback?.warnings.length) {
    summary.push(`warnings=${fallback.warnings.join(";")}`);
  }
  return summary;
}

export function getGcExplanationFromPlan(
  plan: GcPlan,
): GcExplanation {
  return {
    blocked: [...plan.blockedByDependency],
    temporalBlocked: plan.temporalBlocked ? [...plan.temporalBlocked] : undefined,
    reasons: plan.candidates.map((c) => `${c.version}:${c.reason}`),
  };
}

export function getGcExplanation(
  traceIdOrPlan: string | GcPlan,
  planOrModel?: GcPlan | UnifiedSelectorCausalModel,
): GcExplanation {
  if (typeof traceIdOrPlan !== "string") {
    return getGcExplanationFromPlan(
      traceIdOrPlan,
      planOrModel as UnifiedSelectorCausalModel | undefined,
    );
  }
  const traceId = traceIdOrPlan;
  if (
    planOrModel &&
    typeof planOrModel === "object" &&
    "candidates" in planOrModel &&
    "blockedByDependency" in planOrModel
  ) {
    return getGcExplanationFromPlan(planOrModel as GcPlan);
  }
  const explanation = getExplanation(traceId);
  return (
    explanation.gc ?? {
      blocked: [],
      reasons: [`no gc plan for traceId=${traceId}`],
    }
  );
}

export function getFallbackExplanation(traceId: string): FallbackExplainabilityResult {
  const decision = getTraceById(traceId);
  const fallbackTrace = getLastFallbackTrace();
  const runtimeContext =
    decision?.runtimeContext ?? getLastRuntimeContextSnapshot() ?? undefined;

  return resolveExplainability({
    expectedVersion: decision?.snapshotVersion ?? fallbackTrace?.selectedVersion ?? "v0",
    runtimeContext,
    partialRegistry: {},
    pointerPrevious: undefined,
    pointerEpoch: runtimeContext?.pointerEpoch ?? fallbackTrace?.pointerEpoch,
  });
}

export type { CausalSemanticIntent } from "@/lib/selector-core/selector-causal-semantic-router";

function buildForensicExplanation(traceId: string): UnifiedExplanation {
  try {
    const decision = getTraceById(traceId);
    const fallback = getFallbackExplanation(traceId);
    const runtimeContext =
      decision?.runtimeContext ?? getLastRuntimeContextSnapshot() ?? undefined;

    const routed = routeCausalExplanation("FORENSIC", {
      decisionTrace: decision,
      fallbackTrace: fallback.trace,
      runtimeContext,
    });
    const causalModel = routed.model;

    const degradationMode = decision ? fallback.mode : "FORENSIC";
    const summary = decision
      ? buildSummary(traceId, degradationMode, decision, fallback)
      : [
          `traceId=${traceId}`,
          "decision trace not found",
          `degradationMode=${degradationMode}`,
          "forensic envelope returned",
        ];

    return {
      traceId,
      decision,
      fallback,
      causalModel,
      causalIndex: causalModel,
      degradationMode,
      summary,
      valid: true,
    };
  } catch {
    const empty = createEmptyCausalModel();
    return {
      traceId,
      causalModel: empty,
      causalIndex: empty,
      degradationMode: "FORENSIC",
      summary: [`traceId=${traceId}`, "explanation recovered via forensic envelope"],
      valid: true,
    };
  }
}

function buildUxExplanation(traceId: string): UnifiedExplanation {
  const decision = getTraceById(traceId);
  const fallback = getFallbackExplanation(traceId);
  const degradationMode = decision ? fallback.mode : "FORENSIC";
  const empty = createEmptyCausalModel();

  return {
    traceId,
    decision,
    fallback,
    causalModel: empty,
    causalIndex: empty,
    degradationMode,
    summary: decision
      ? buildSummary(traceId, degradationMode, decision, fallback)
      : [`traceId=${traceId}`, "decision trace not found", `degradationMode=${degradationMode}`],
    valid: true,
  };
}

function buildDebugExplanation(traceId: string): UnifiedExplanation {
  const decision = getTraceById(traceId);
  const fallback = getFallbackExplanation(traceId);
  const runtimeContext =
    decision?.runtimeContext ?? getLastRuntimeContextSnapshot() ?? undefined;

  const routing = routeCausalExplanation("DEBUG", {
    decisionTrace: decision,
    fallbackTrace: fallback.trace,
    runtimeContext,
  });

  return {
    traceId,
    decision,
    fallback,
    causalModel: routing.model,
    causalIndex: routing.model,
    degradationMode: decision ? fallback.mode : "FORENSIC",
    summary: [
      ...buildSummary(traceId, fallback.mode, decision, fallback),
      "intent=DEBUG",
      `views=${routing.views.length}`,
    ],
    valid: true,
  };
}

function buildAuditExplanation(traceId: string): UnifiedExplanation {
  const decision = getTraceById(traceId);
  const fallback = getFallbackExplanation(traceId);
  const runtimeContext =
    decision?.runtimeContext ?? getLastRuntimeContextSnapshot() ?? undefined;

  const routing = routeCausalExplanation("AUDIT", {
    decisionTrace: decision,
    fallbackTrace: fallback.trace,
    runtimeContext,
  });

  const gcView = routing.views.find((v) => v.viewType === "gc") ?? routing.views[0]!;

  return {
    traceId,
    decision,
    fallback,
    gc: getGcExplanation(traceId),
    causalModel: routing.model,
    causalIndex: routing.model,
    degradationMode: decision ? fallback.mode : "FORENSIC",
    summary: [`traceId=${traceId}`, "intent=AUDIT", `gcEvents=${gcView.eventCount}`],
    valid: true,
  };
}

/** @advisory v5.7 — single public explainability entrypoint (intent routes internally). */
export function getExplanation(
  traceId: string,
  intent: CausalSemanticIntent = "FORENSIC",
): UnifiedExplanation {
  switch (intent) {
    case "UX":
      return buildUxExplanation(traceId);
    case "DEBUG":
      return buildDebugExplanation(traceId);
    case "AUDIT":
      return buildAuditExplanation(traceId);
    case "FORENSIC":
    default:
      return buildForensicExplanation(traceId);
  }
}

/** @deprecated v5.5 — use getExplanation */
export function getSelectorExplanation(traceId: string): UnifiedExplanation {
  return getExplanation(traceId);
}

